#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library. Author the
# per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

BASIC_COUNT=1
SKILL_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
source "$SKILL_DIR/scripts/setup-input.sh"
export PATH="$HOME/.local/bin:/opt/homebrew/bin:/usr/local/bin:$PATH"
case "$(uname -s)" in MINGW*|MSYS*|CYGWIN*) echo 'Windows 请双击 install\setup.cmd。' >&2; exit 2 ;; esac
MODE=""
GROUP_LIBRARY=0
ADVANCED=0
export PAPER2ZOTERO_AGENT="${PAPER2ZOTERO_AGENT:-auto}"
while (( $# )); do
  case "$1" in
    --help)
      echo 'Usage: bash install/setup.sh [--dependencies-only | --check | --modules [runtime skills zotero mineru kimi]] [--advanced] [--group] [--agent auto|codex|claude-code|pi|all]'
      exit 0 ;;
    --group) GROUP_LIBRARY=1 ;;
    --advanced) ADVANCED=1 ;;
    --agent)
      [[ $# -ge 2 ]] || { echo '--agent needs a value' >&2; exit 2; }
      PAPER2ZOTERO_AGENT="$2"; shift ;;
    --modules)
      [[ -z "$MODE" ]] || { echo 'Choose one setup mode' >&2; exit 2; }
      shift; exec bash "$SKILL_DIR/scripts/bootstrap.sh" --modules "$@" ;;
    --dependencies-only|--check)
      [[ -z "$MODE" ]] || { echo 'Choose one setup mode' >&2; exit 2; }
      MODE="$1" ;;
    *) echo 'Unknown option; use --help' >&2; exit 2 ;;
  esac
  shift
done
case "$PAPER2ZOTERO_AGENT" in auto|codex|claude-code|pi|all) ;; *) echo 'Unknown agent; use --help' >&2; exit 2;; esac
if [[ "$MODE" == --dependencies-only ]]; then
  exec bash "$SKILL_DIR/scripts/bootstrap.sh" --dependencies-only
fi
if [[ "$MODE" == --check ]]; then
  if [[ "$GROUP_LIBRARY" == 1 ]]; then
    exec bash "$SKILL_DIR/scripts/bootstrap.sh" --check --group
  fi
  exec bash "$SKILL_DIR/scripts/bootstrap.sh" --check
fi
if [[ "$ADVANCED" == 1 ]]; then
  TOTAL_STAGES=2
  [[ "$GROUP_LIBRARY" == 1 ]] && TOTAL_STAGES=3
else
  TOTAL_STAGES=$((3 + BASIC_COUNT))
  [[ "$GROUP_LIBRARY" == 1 ]] && TOTAL_STAGES=$((TOTAL_STAGES + 1))
fi
umask 077
ENV_FILE="$HOME/.config/literature-to-zotero/env"
[[ -t 0 ]] || { echo '请在交互终端运行 setup；Agent 可先用 --dependencies-only。'; exit 2; }
connect_account() {
  local service="$1" value="$2"
  local args=(--connect "$service")
  if [[ "$service" == zotero && "$GROUP_LIBRARY" == 1 ]]; then
    args+=(--group --group-id "${ZOTERO_LIBRARY_ID:-}")
  fi
  printf '%s' "$value" | "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" "${args[@]}"
}

shared_guide() {
  "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" --guide "$1"
}

_clear
printf '\n%s%s  把论文和阅读笔记放进 Zotero%s\n\n' "$BOLD" "$BLUE" "$RESET"
say '工具由安装器准备，你只需要打开本机 Zotero 的本地接口。'
say '基础配置检查三件事。scansci-pdf 1.19.0 能导入，全文转换有一条可用通路，本机 Zotero 能写入。'
note 'Ctrl-C 可退出，已保存内容会保留。'
if [[ "$ADVANCED" == 1 ]]; then note '已打开更多配置：MinerU 云端 Token 或自建 MinerU 地址。'; fi
pause '按回车开始'

stage "准备工具和 AI 助手"
bash "$SKILL_DIR/scripts/bootstrap.sh" --runtime-only
IFS= read -r PYTHON_BIN < "$HOME/.config/literature-to-zotero/python-path"
export PYTHON_BIN
if ! "$PYTHON_BIN" "$SKILL_DIR/scripts/install.py" --detect; then
  say '你要在哪个 AI 助手中使用？1 = Codex，2 = Claude Code，3 = Pi'
  while true; do
    printf '  输入 1、2 或 3：'
    IFS= read -r AGENT_CHOICE || { note '配置已暂停，重跑向导可继续。'; exit 130; }
    case "$AGENT_CHOICE" in
      1) PAPER2ZOTERO_AGENT=codex; break ;;
      2) PAPER2ZOTERO_AGENT=claude-code; break ;;
      3) PAPER2ZOTERO_AGENT=pi; break ;;
      *) warn '请选择一个助手。' ;;
    esac
  done
fi
bash "$SKILL_DIR/scripts/install-skill.sh"
if [[ "$ADVANCED" == 0 ]]; then
pause '准备完成，回车检查本机 Zotero'

stage "Zotero 本地 API"
if [[ "$(uname -s)" == Darwin ]] && { [[ -d /Applications/Zotero.app ]] || [[ -d "$HOME/Applications/Zotero.app" ]]; }; then
  open -a Zotero || true
elif ! command -v zotero >/dev/null 2>&1; then
  open_url 'https://www.zotero.org/download'
fi
step '1. 打开 Zotero，进入 设置 → 高级。'
step '2. 勾选「允许此计算机上的其他应用程序与 Zotero 通讯」。'
note 'Zotero 弹出授权框时选「始终允许」。'
pause '完成后回车检查'
if ! "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" --extra desktop; then
  warn '尚未启用，已保存的配置保留；可在准备完成后回来检查。'
fi
pause '按回车继续'
fi

if [[ "$GROUP_LIBRARY" == 1 ]]; then
stage "连接 Zotero Web API"
say '群组文库需要 Web API 授权码。个人文库写入走本机 Desktop，不在这一步手填个人文库 ID。'
open_url 'https://www.zotero.org/settings/keys'
step '1. 登录 Zotero。还没有账号，可先在网页上注册。'
step '2. 新建授权码，勾选 Allow library access、Allow notes access、Allow write access。'
step '3. 允许目标群组的读取和写入。'
step '4. 复制 Key，粘贴到下方。'
while true; do
  ask_authorization ZOTERO_API_KEY '粘贴 Zotero 授权码（没有则回车跳过）：'
  if [[ -n "$ZOTERO_API_KEY" ]]; then
    ask ZOTERO_LIBRARY_ID '填写要保存到的群组文库 ID（数字；回车稍后配置）：'
    if connect_account zotero "$ZOTERO_API_KEY"; then
      unset ZOTERO_API_KEY ZOTERO_LIBRARY_ID ZOTERO_LIBRARY_TYPE
    else
      unset ZOTERO_API_KEY ZOTERO_LIBRARY_ID ZOTERO_LIBRARY_TYPE
      warn '连接未完成；原有账号已保留，无需手动查找个人文库 ID。'
      if retry_connection; then continue; fi
    fi
  else
    note '已跳过 Zotero Web API；群组写入需稍后补齐。'
  fi
  break
done
pause 'Web API 这一步结束，按回车继续'
fi

if [[ "$ADVANCED" == 0 ]]; then
stage "检查结果，开始使用"
check_args=(--check)
[[ "$GROUP_LIBRARY" == 1 ]] && check_args+=(--group)
if "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" "${check_args[@]}"; then
  pause '检查通过，回车查看结果'
  _clear
  say '✓ 配置完成。回到你的 AI 助手，试着说：'
  say '“帮我找近三年 AI 心理健康干预的研究，先给我一份候选清单。”'
  note '如果暂时找不到技能，新开一个助手会话再试。'
else
  warn '部分配置尚未完成；已填写内容保留，重跑 setup 即可继续。'
  SETUP_RESULT=1
fi
fi

if [[ "$ADVANCED" == 1 ]] || confirm '配置 MinerU？可选，不配置就用本机 markitdown 转换 PDF'; then
stage "更多配置（可选）· MinerU"
say 'PDF 转 Markdown 时先用 MinerU，失败或不配置时用本机 markitdown。'
say '1 = MinerU 云端 Token，2 = 自建 MinerU 地址（IP 或域名），回车跳过'
while true; do
  printf '  输入 1、2 或回车：'
  IFS= read -r MINERU_CHOICE || MINERU_CHOICE=''
  case "$MINERU_CHOICE" in
    1) service=mineru; setting=MINERU_TOKEN ;;
    2) service=mineru_api; setting=MINERU_API_BASE ;;
    '') note '已跳过，原有设置保留。'; break ;;
    *) warn '请输入 1、2，或直接回车跳过。'; continue ;;
  esac
  shared_guide "$service"
  if [[ "$service" == mineru ]]; then
    ask_authorization "$setting" '粘贴 MinerU Token（可留空）：'
  else
    ask "$setting" 'MinerU 服务地址（可留空）：'
  fi
  value="${!setting}"
  unset "$setting"
  if [[ -z "$value" ]]; then
    note '没有填写，原有设置保留。'
  elif ! printf '%s' "$value" | "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" --extra "$service"; then
    warn '本项未保存，原有设置保留。'
    unset value
    if retry_connection; then continue; fi
  fi
  unset value
  break
done
fi
note '更多配置可随时重新打开：bash install/setup.sh --advanced。无需重填基础账号。'

say '总结提示词可以换成你更熟悉的版本，保留默认也可以直接使用。'
if confirm '想换用自己的总结提示词？查看需要修改的文件位置'; then
  say '需要修改的文件：'
  "$PYTHON_BIN" - "$SKILL_DIR/scripts" "$PAPER2ZOTERO_AGENT" <<'PY'
import sys
from pathlib import Path
sys.path.insert(0, sys.argv[1])
from agent_installation import installed_paths
paths = dict.fromkeys(str((Path(root) / 'references' / 'paper-summary.md').resolve())
                      for root in installed_paths(agent=sys.argv[2]))
for path in paths:
    print('  ' + path)
if not paths:
    print('  在当前助手实际加载的 paper-to-zotero 目录中，找到 references/paper-summary.md。')
PY
  step '用文本编辑器打开该 Markdown 文件，将开头的阅读分析要求换成自己的提示词。'
  step '保留“## Save and continue”及之后的保存、续跑说明；无需修改账号配置。'
  note '保存后在新文献任务中使用；已有笔记不会自动重写。托管更新会保留自定义提示词，也建议自行保存副本。'
  note '这里只提供修改位置，不打开编辑器、不修改文件。'
fi

exit "${SETUP_RESULT:-0}"
